function App() {
  const [phase, setPhase] = useState('loading');
  const data = phase === 'data' ? ['Ada', 'Linus'] : [];

  let content;
  if (phase === 'loading') content = <p>Loading…</p>;
  else if (phase === 'error') content = <p style={{ color: 'crimson' }}>Something went wrong.</p>;
  else if (data.length === 0) content = <p>No users found.</p>;
  else content = <ul>{data.map(n => <li key={n}>{n}</li>)}</ul>;

  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      {content}
      <div style={{ marginTop: 8 }}>
        <button onClick={() => setPhase('loading')}>Loading</button>
        <button onClick={() => setPhase('error')} style={{ marginLeft: 4 }}>Error</button>
        <button onClick={() => setPhase('empty')} style={{ marginLeft: 4 }}>Empty</button>
        <button onClick={() => setPhase('data')} style={{ marginLeft: 4 }}>Data</button>
      </div>
    </div>
  );
}

